function shortProgramGains(focus,rating,kind){
  const primary=rating>=9?3:rating>=6?2:1;
  const gains={[focus]:primary};
  const threshold=kind==='lecture'?.45:.50;
  for(const[skill,weight]of Object.entries(ADJACENCY[focus]||{})){
    if(primary>=2&&weight>=threshold)gains[skill]=Math.max(1,Math.round(primary*weight));
  }
  return gains;
}
function longProgramGains(focus,rating,kind){
  const primary=kind==='university'?(rating>=46?5:rating>=40?4:3):(rating>=8?3:rating>=6?2:1);
  const gains=Object.fromEntries(SKILL_IDS.map(id=>[id,1]));
  gains[focus]=primary;
  for(const[skill,weight]of Object.entries(ADJACENCY[focus]||{})){
    gains[skill]=Math.max(gains[skill],Math.max(1,Math.round(primary*weight)));
  }
  return gains;
}
function buildCourse(row){
  return {...row,icon:ICONS[row.focus],type:'course',ratingMax:10,ratingLabel:'сложность',cost:900+row.rating*450,durationDays:18+row.rating*3,skillGains:shortProgramGains(row.focus,row.rating,'course'),repeatCount:1,reqLevel:Math.max(1,row.rating-5),reqSkills:row.rating>=8?{[row.focus]:2}:undefined};
}
function buildLecture(row){
  return {...row,icon:'LEC',type:'lecture',ratingMax:10,ratingLabel:'уровень',cost:500+row.rating*180,durationDays:10+row.rating*2,skillGains:shortProgramGains(row.focus,row.rating,'lecture'),repeatCount:1,reqLevel:Math.max(1,row.rating-6),reqSkills:row.rating>=9?{[row.focus]:2}:undefined};
}
function buildCollege(row){
  return {...row,icon:'ТЕХ',type:'college',ratingMax:10,ratingLabel:'подготовка',cost:12000+row.rating*4500,durationDays:720,academicYears:2,skillGains:longProgramGains(row.focus,row.rating,'college'),repeatCount:1,reqLevel:Math.max(3,row.rating-3),reqSkills:row.rating>=8?{[row.focus]:1}:undefined,graduationBonus:{playerXp:500+row.rating*80,reputation:35+row.rating*5,salaryBonus:.05+row.rating*.006}};
}
function buildUniversity(row){
  return {...row,icon:'ВУЗ',type:'university',ratingMax:50,ratingLabel:'подготовка',cost:Math.round(row.rating*3800),durationDays:1440,academicYears:4,skillGains:longProgramGains(row.focus,row.rating,'university'),repeatCount:1,reqLevel:Math.max(7,Math.round(row.rating/5)),reqSkills:{[row.focus]:Math.max(2,Math.round(row.rating/15))},graduationBonus:{playerXp:900+row.rating*24,reputation:70+row.rating*2,salaryBonus:.12+row.rating*.003}};
}
function buildForum(row){
  return {...row,icon:'WEB',type:'forum',ratingMax:5,ratingLabel:'авторитет',cost:0,durationDays:8+row.rating*2,skillGains:{[row.focus]:1},repeatCount:row.rating,reqLevel:Math.max(1,row.rating-3),forumMastery:true};
}

export const EDUCATION_V152=[
  ...COURSE_ROWS.map(buildCourse),
  ...LECTURE_ROWS.map(buildLecture),
  ...COLLEGE_ROWS.map(buildCollege),
  ...UNIVERSITY_ROWS.map(buildUniversity),
  ...FORUM_ROWS.map(buildForum)
];
